@startuml

class Ingredient {
  + Name : string
  + MeasuringUnit : string
  + QuantityInStock : float
}

class Dish {
  + Name : string
  + Identifier : int
}

class DishIngredient {
  + Quantity : float
}

class Table {
  + Identifier : int
  + MaxPeople : int
}

class Meal {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class MealDish {
  + Quantity : int
}

class Waiter {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Client {
  + TaxIdentificationNumber : string
  + Name : string
  + Address : string
}

Dish "1" -- "*" DishIngredient : is composed of
Ingredient "1" -- "*" DishIngredient : is used in
Dish "*" -- "*" Meal : is consumed in
MealDish "*" -- "1" Meal
MealDish "*" -- "1" Dish
Meal "1" -- "1" Table : takes place at
Meal "0..1" -- "0..1" Client : consumed by
Meal "*" -- "1" Waiter : is served by

@enduml

